import {esc} from '../editor/model.js';
import {icon} from '../../shared/icons.js';
import {visibleTasks,taskCounts,loadRemovedTasks,saveRemovedTasks} from './task-data.js';
const statusOptions=['全部','运行中','已完成','失败','已阻塞','已暂停','部分完成','等待上游','待运行','已取消'];
import {renderTaskCard as taskCard} from './task-card.js';
export const taskViewState=()=>({query:'',type:'全部',status:'全部',page:1,pageSize:5,expanded:new Set()});
export function renderTaskManager(){return `<main class="task-manager page-main" data-ui><header class="task-manager-heading"><h1>任务管理</h1><span>原型演示 · 微观模拟与跨尺度模拟</span></header><div class="task-manager-filters"><label class="task-manager-search">${icon('search')}<input type="search" placeholder="搜索任务名称或编号…" aria-label="搜索任务"></label><label><span class="sr-only">任务类型</span><select data-task-type aria-label="任务类型"><option value="全部">所有类型</option><option>微观模拟</option><option>跨尺度模拟</option></select></label><label><span class="sr-only">任务状态</span><select data-task-status aria-label="任务状态">${statusOptions.map(x=>`<option value="${x}">${x==='全部'?'所有状态':x}</option>`).join('')}</select></label><button class="btn" data-tasks-clear>清空筛选</button></div><div class="task-manager-counts" aria-label="任务统计"></div><div class="task-manager-list-heading"><span data-task-total></span><button data-tasks-restore hidden>恢复已移除任务</button></div><section class="task-manager-records" aria-label="任务列表"></section><footer class="task-manager-pagination"></footer></main>`;}

export function mountTaskManager(root,{getRecords,view,navigate,openDialog,notify}){
 let removed=loadRemovedTasks();const q=s=>root.querySelector(s);
 q('input[type=search]').value=view.query;q('[data-task-type]').value=view.type;q('[data-task-status]').value=view.status;
 function refresh(){const records=getRecords(),base=visibleTasks(records,{...view,status:'全部'},removed),filtered=visibleTasks(records,view,removed),counts=taskCounts(base),pages=Math.max(1,Math.ceil(filtered.length/view.pageSize));view.page=Math.min(pages,Math.max(1,view.page));
 q('.task-manager-counts').innerHTML=[['全部','总任务数',counts.total,'grid'],['运行中','运行中',counts.running,'flow'],['已完成','已完成',counts.completed,'check'],['失败','失败',counts.failed,'close']].map(([id,label,count,symbol])=>`<button data-task-count="${id}" aria-pressed="${view.status===id}" data-state="${id}"><div><span>${label}</span><strong>${count}</strong></div>${icon(symbol)}</button>`).join('');
 q('[data-task-total]').textContent=`共 ${filtered.length} 个任务 · 按搜索与类型统计`;q('[data-tasks-restore]').hidden=!removed.size;
 q('.task-manager-records').innerHTML=filtered.slice((view.page-1)*view.pageSize,view.page*view.pageSize).map(t=>taskCard(t,view.expanded.has(t.key))).join('')||'<div class="task-manager-empty"><h2>没有符合条件的任务</h2><p>调整搜索词、类型或状态后再试。</p><button class="btn" data-tasks-clear>清空筛选</button></div>';
 q('.task-manager-pagination').innerHTML=`<span>共 ${filtered.length} 条</span><label>每页<select data-task-page-size aria-label="每页任务数"><option value="5" ${view.pageSize===5?'selected':''}>5条</option><option value="10" ${view.pageSize===10?'selected':''}>10条</option><option value="20" ${view.pageSize===20?'selected':''}>20条</option></select></label><button data-task-page="${view.page-1}" ${view.page===1?'disabled':''} aria-label="上一页">${icon('chevron')}</button><span class="task-page-position">${view.page} / ${pages}</span><button data-task-page="${view.page+1}" ${view.page===pages?'disabled':''} aria-label="下一页">${icon('chevron')}</button>`;
 }
 function clear(){Object.assign(view,{query:'',type:'全部',status:'全部',page:1});q('input[type=search]').value='';q('[data-task-type]').value='全部';q('[data-task-status]').value='全部';refresh();}
 function showDetail(t){if(t.type==='跨尺度模拟'){navigate(`/multiscale/workflows/${encodeURIComponent(t.workflowId)}/edit?executionId=${encodeURIComponent(t.runId)}`);return;}const dialog=openDialog(`<div class="dialog-form task-detail-dialog"><h2>${esc(t.name)}</h2><div class="task-detail-state"><span class="task-state-badge" data-state="${t.status}">${esc(t.status)}</span><span class="task-type-badge">${t.type}</span><span>${esc(t.property)}</span></div><p class="task-detail-id">${esc(t.id)}</p>${t.reason?`<p class="task-detail-problem">${esc(t.reason)}</p>`:''}<h3>任务信息</h3><dl><dt>提交时间</dt><dd>${esc(t.time)}</dd><dt>任务来源</dt><dd>${esc(t.source)}</dd>${t.workflowId?`<dt>关联建模</dt><dd>${esc(t.definitionName||t.source)}</dd><dt>提交版本</dt><dd>v${esc(t.definitionRevision??'—')}</dd>`:''}</dl>${t.definitionSnapshot?`<details class="task-snapshot-details"><summary>本次建模与工作流快照（只读）</summary><pre>${esc(JSON.stringify(t.definitionSnapshot,null,2))}</pre></details>`:''}<h3>执行日志</h3><pre>${esc(t.logs?.join('\n')||'暂无日志。')}</pre><div class="dialog-actions"><button class="btn" data-dialog-close>关闭</button>${t.workflowId?`<button class="btn" data-open-task-definition>打开关联建模</button><button class="btn primary" data-open-task-workspace>${t.status==='已阻塞'||t.status==='失败'?'处理本次任务':'查看本次任务'}</button>`:'<span class="task-detail-demo">独立微观任务为原型演示数据</span>'}</div></div>`);dialog.querySelector('[data-open-task-definition]')?.addEventListener('click',()=>{dialog.close();navigate(`/multiscale/workflows/${encodeURIComponent(t.workflowId)}/edit`);});dialog.querySelector('[data-open-task-workspace]')?.addEventListener('click',()=>{dialog.close();navigate(`/multiscale/workflows/${encodeURIComponent(t.workflowId)}/edit?executionId=${encodeURIComponent(t.runId)}${t.nodeId?'&nodeId='+encodeURIComponent(t.nodeId):''}`);});}
 const input=e=>{if(e.target.matches('input[type=search]')){view.query=e.target.value;view.page=1;refresh();}};
 const change=e=>{if(e.target.matches('[data-task-type]'))view.type=e.target.value;else if(e.target.matches('[data-task-status]'))view.status=e.target.value;else if(e.target.matches('[data-task-page-size]'))view.pageSize=Number(e.target.value);else return;view.page=1;refresh();};
 const click=e=>{if(e.target.closest('[data-tasks-clear]'))return clear();if(e.target.closest('[data-tasks-restore]')){removed=new Set();saveRemovedTasks(removed);refresh();return notify('已恢复从列表移除的任务');}
 const count=e.target.closest('[data-task-count]');if(count){view.status=count.dataset.taskCount;q('[data-task-status]').value=view.status;view.page=1;refresh();return;}
 const page=e.target.closest('[data-task-page]');if(page){view.page=Number(page.dataset.taskPage);refresh();q('.task-manager-list-heading').scrollIntoView({behavior:'smooth',block:'start'});return;}
 const action=e.target.closest('[data-task-op]');if(!action)return;const t=getRecords().find(t=>t.key===action.dataset.key);if(!t)return;
 if(action.dataset.taskOp==='params'){view.expanded.has(t.key)?view.expanded.delete(t.key):view.expanded.add(t.key);refresh();}
 if(action.dataset.taskOp==='detail')showDetail(t);
 if(action.dataset.taskOp==='view'){showDetail(t);}
 if(action.dataset.taskOp==='remove'){const dialog=openDialog(`<div class="dialog-form"><h2>从任务列表移除</h2><p>移除“${esc(t.name)}”的列表记录？</p><p>不会取消正在运行的任务，也不会删除工作流、日志或执行快照，可在列表中恢复。</p><div class="dialog-actions"><button class="btn" data-dialog-close>取消</button><button class="btn primary" data-confirm-task-remove>移除记录</button></div></div>`);dialog.querySelector('[data-confirm-task-remove]').onclick=()=>{removed.add(t.key);saveRemovedTasks(removed);dialog.close();refresh();notify('任务已从列表移除，可点击恢复');};}
 };
 root.addEventListener('input',input);root.addEventListener('change',change);root.addEventListener('click',click);
 const progress=()=>refresh();document.addEventListener('forge:run-progress',progress);refresh();
 return()=>{root.removeEventListener('input',input);root.removeEventListener('change',change);root.removeEventListener('click',click);document.removeEventListener('forge:run-progress',progress);};
}
